const p = $('Prep').first().json;
const v = $input.first()?.json?.embedding?.values;
const hasValidVector = Array.isArray(v) && v.length === 768;

const mustFilters = [
  { key: 'status', match: { any: p.statuses } },
  { key: 'role_access', match: { any: p.roles } },
  { key: 'branch_scope', match: { any: p.branches } }
];

// Nếu không phải chế độ kiểm thử thì lọc chặt ngày hiệu lực
if (!p.is_testing_scope) {
  mustFilters.push({ key: 'effective_int', range: { lte: p.today } });
  mustFilters.push({ key: 'expiry_int', range: { gte: p.today } });
}

if (!hasValidVector) {
  // Vector không khả dụng (API sự cố hoặc fallback): gửi query rỗng để Qdrant không văng lỗi
  return [{ json: { body: { filter: { must: mustFilters }, limit: 0, with_payload: true }, has_vector: false } }];
}

return [{ json: { body: { vector: v, limit: 20, with_payload: true, filter: { must: mustFilters } }, has_vector: true } }];

const dense = ($('Qdrant Search').first()?.json?.result) || [];
const kw = ($('PG Keyword').all() || []).map(i => i.json).filter(r => r && r.chunk_id);
const K = 60;
const score = {};

// 1. Dynamic Weighting theo chất lượng dense vector
const topDenseSim = dense.length ? Number(dense[0]?.score || 0) : 0;
const kwWeight = topDenseSim < 0.70 ? 1.6 : 1.0;
const denseWeight = 1.0;

for (let i = 0; i < dense.length; i++) {
  const id = String(dense[i]?.payload?.chunk_id || '').toLowerCase();
  if (!/^[0-9a-f-]{36}$/.test(id)) continue;
  score[id] = (score[id] || 0) + (denseWeight / (K + i + 1));
}

for (let i = 0; i < kw.length; i++) {
  const id = String(kw[i]?.chunk_id || '').toLowerCase();
  if (!/^[0-9a-f-]{36}$/.test(id)) continue;
  score[id] = (score[id] || 0) + (kwWeight / (K + i + 1));
}

// 2. Bảo toàn tuyệt đối cho Top 3 BM25 Keyword Matches từ PostgreSQL
const guaranteedKwIds = kw.slice(0, 3)
  .map(k => String(k.chunk_id).toLowerCase())
  .filter(id => /^[0-9a-f-]{36}$/.test(id));

const sortedIds = Object.entries(score)
  .sort((a, b) => b[1] - a[1])
  .map(e => e[0])
  .filter(x => /^[0-9a-f-]{36}$/.test(x));

// Kết hợp: ưu tiên các mục có điểm RRF cao nhất, đồng thời bảo toàn chắc chắn các top keyword
const combinedSet = new Set();
for (const id of guaranteedKwIds) combinedSet.add(id);
for (const id of sortedIds) {
  combinedSet.add(id);
  if (combinedSet.size >= 14) break;
}

const ids = [...combinedSet];
const pass = ids.length > 0;
const best = topDenseSim > 0 ? topDenseSim : (kw.length > 0 ? 0.75 : 0);

return [{ json: {
  ids,
  ids_sql: '{' + ids.join(',') + '}',
  best_sim: best,
  dense_count: dense.length,
  keyword_count: kw.length,
  rrf_count: ids.length,
  pass
} }];

const COMPANY = 'Toàn tập đoàn SOTRANS (SOTRANS, Sowatco, Vietranstimex)';
const HR_CONTACT = '028 1234 5678 hoặc hr@sotrans.vn';

const PROMPT = `
# VAI TRÒ
Bạn là Trợ lý AI chuyên trách Tra cứu Quy định & Chính sách nội bộ của {{company_name}}.

# NGUỒN SỰ THẬT DUY NHẤT
Nguồn dữ liệu DUY NHẤT được phép sử dụng để trả lời là các thẻ <tai_lieu> ở cuối prompt.
Tuyệt đối không sử dụng kiến thức nền, trí nhớ ngoài, luật lao động chung không có trong tài liệu, suy đoán hoặc bịa đặt.

# NGUYÊN TẮC TRẢ LỜI DỰA TRÊN BẰNG CHỨNG (EVIDENCE-BASED)
1. CÓ BẰNG CHỨNG TRỰC TIẾP:
   - Trả lời thẳng thắn, chính xác, bám sát từng câu chữ và số liệu trong tài liệu.
   - Nêu rõ số tiền, thời hạn, tỷ lệ, ngày tháng, điều kiện, đối tượng áp dụng và thẩm quyền phê duyệt chính xác theo tài liệu.
2. TỔNG HỢP NHIỀU ĐOẠN / NHIỀU MỤC:
   - Khi câu hỏi liên quan đến nhiều điều khoản (ví dụ quy định chung, thủ tục, ngoại lệ, chế tài), tổng hợp đầy đủ và logic, không bỏ sót các điều kiện tiên quyết hoặc ngoại lệ quan trọng.
3. BẢNG BIỂU & MA TRẬN TRÁCH NHIỆM (RACI MATRIX / CHECKLIST):
   - Khi thông tin nằm trong bảng hoặc ma trận RACI, đọc và trình bày rõ ràng: người thực hiện (R), người chịu trách nhiệm chính (A), người được tham vấn (C), người nhận thông tin (I) hoặc danh mục kiểm tra.
4. TÀI LIỆU KIỂM THỬ / DỰ THẢO (TESTING):
   - Nếu thông tin trích xuất từ tài liệu có trạng thái "testing", hãy nêu rõ: *(Lưu ý: Nội dung này được trích xuất từ bản dự thảo / kiểm thử chưa ban hành chính thức)*.
5. NHIỀU TÀI LIỆU HOẶC NHIỀU PHIÊN BẢN (v1 vs v2):
   - Phiên bản có số hiệu lớn hơn (ví dụ v2 thay thế v1) hoặc có ngày hiệu lực mới hơn thay thế phiên bản cũ.
   - Quy định đặc thù của công ty con (VTX, SWC, STL) ưu tiên áp dụng cho nhân sự thuộc công ty đó so với quy chế khung chung của tập đoàn.
6. THÔNG TIN KHÔNG ĐỦ HOẶC CÂU HỎI MƠ HỒ:
   - Nếu tài liệu chỉ có thông tin một phần, trả lời phần đã xác minh và nói rõ phần chưa có quy định trong tài liệu được cấp.
   - Nếu hoàn toàn không có thông tin trong <tai_lieu>, đặt answerable=false.

# ĐỊNH DẠNG TRẢ LỜI
Chỉ trả về MỘT JSON hợp lệ:
{"answerable":bool,"answer":string,"citations":[{"chunk_id":string,"evidence_quote":string}],"missing_info":string}

# QUY TẮC CITATION
- Mỗi citation trỏ tới đúng chunk_id trong <tai_lieu> (ví dụ C1, C2...).
- evidence_quote PHẢI là chuỗi trích nguyên văn từ chunk đó (khoảng 5 - 35 từ).
- Tuyệt đối không tự bịa chunk_id.

# KHI KHÔNG CÓ THÔNG TIN
Trả đúng:
{"answerable":false,"answer":"Hiện tại tài liệu nội bộ được cung cấp chưa có thông tin về nội dung bạn hỏi. Để được hướng dẫn chi tiết, bạn vui lòng liên hệ phòng Nhân sự: {{hr_contact}}.","citations":[],"missing_info":"Không tìm thấy căn cứ trong tài liệu được truy xuất."}

# TÀI LIỆU TRUY XUẤT ĐƯỢC
{{retrieved_context}}
`;

const order = $('RRF').first().json.ids || [];
const p = $('Prep').first().json;

const rows = Object.fromEntries(
  $input.all()
    .map(i => i.json)
    .filter(r => r && r.chunk_id)
    .map(r => [String(r.chunk_id).toLowerCase(), r])
);

const map = {};
const parts = [];

order.filter(id => rows[id]).forEach((id, k) => {
  const r = rows[id];
  const cid = 'C' + (k + 1);
  map[cid] = r;
  const safeTitle = String(r.title || '').replace(/[<>]/g, '');
  const safeNumber = String(r.doc_number || 's/n').replace(/[<>]/g, '');
  const safePath = String(r.section_path || '').replace(/[<>]/g, '');
  const statusStr = r.status === 'testing' ? 'trang_thai="testing (bản kiểm thử/dự thảo)"' : 'trang_thai="active (chính thức)"';
  parts.push(
    `<tai_lieu id="${cid}" file="${safeTitle}" so_vb="${safeNumber}" dieu_muc="${safePath}" hieu_luc_tu="${r.effective_date}" phien_ban="v${r.version}" ${statusStr}>${String(r.content || '')}</tai_lieu>`
  );
});

const s = String(p.today);
const vars = {
  company_name: COMPANY,
  current_date: `${s.slice(6,8)}/${s.slice(4,6)}/${s.slice(0,4)}`,
  user_role: p.user_role,
  user_branch: p.user_branch,
  hr_contact: HR_CONTACT,
  retrieved_context: parts.length ? parts.join('\n\n') : '(Không có đoạn văn bản nào)'
};

const system = PROMPT.replace(/\{\{(\w+)\}\}/g, (_, k) => vars[k] ?? '');

return [{ json: {
  map,
  n: parts.length,
  hr_contact: HR_CONTACT,
  gemini_body: {
    systemInstruction: { parts: [{ text: system }] },
    contents: [{ role: 'user', parts: [{ text: p.message }] }],
    generationConfig: {
      temperature: 0,
      maxOutputTokens: 2048,
      responseMimeType: 'application/json'
    }
  }
} }];

const ctx = $('Build_Context').first().json;
const raw = ($json.candidates?.[0]?.content?.parts || [])
  .map(p => p.text || '')
  .join('')
  .trim();

let r = null;
try {
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start >= 0 && end > start) r = JSON.parse(raw.slice(start, end + 1));
} catch (e) {}

const normalize = (s) => String(s ?? '')
  .normalize('NFD')
  .replace(/\p{M}/gu, '')
  .replace(/đ/g, 'd')
  .replace(/Đ/g, 'D')
  .toLowerCase()
  .replace(/\*+/g, '')
  .replace(/[^\p{L}\p{N}]+/gu, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const stripAllowedPrefix = (s) => String(s ?? '')
  .replace(/^\s*(theo\s+tai\s+lieu\s*:?)\s*/i, '')
  .replace(/^\s*(quy\s+dinh\s+ghi\s+nhan\s*:?)\s*/i, '')
  .replace(/^\s*(can\s+cu\s+theo\s*:?)\s*/i, '')
  .replace(/^\s*(\d+[\.\)]|[a-zA-Z][\.\)]|[-•*+#]+)\s*/, '')
  .trim();

const NO = `Hiện tại tài liệu nội bộ mình được cung cấp chưa có thông tin về nội dung bạn hỏi. Bạn vui lòng liên hệ trực tiếp phòng Nhân sự: ${ctx.hr_contact}.`;

const errors = [];
const validCitations = [];
const modelAnswerable = r?.answerable === true;

if (!r || typeof r.answer !== 'string' || !Array.isArray(r.citations)) {
  errors.push('invalid_json_or_schema');
}

if (r && r.answerable === false) {
  r.citations = [];
  if (typeof r.answer !== 'string' || !r.answer.trim()) r.answer = NO;
}

if (modelAnswerable) {
  for (const c of r.citations) {
    const cid = String(c?.chunk_id || '').trim();
    const chunk = ctx.map?.[cid];
    const quote = String(c?.evidence_quote || '').trim();

    if (!chunk) {
      errors.push(`unknown_chunk:${cid}`);
      continue;
    }

    if (!quote) {
      errors.push(`empty_evidence:${cid}`);
      continue;
    }

    const contentN = normalize(chunk.content);
    const quoteN = normalize(quote);

    let quoteMatched = quoteN && contentN.includes(quoteN);
    if (!quoteMatched && quoteN) {
      const qWords = quoteN.split(/\s+/).filter(w => w.length >= 2);
      if (qWords.length >= 3) {
        for (let qi = 0; qi <= qWords.length - 3; qi++) {
          const sub = qWords.slice(qi, qi + 3).join(' ');
          if (contentN.includes(sub)) {
            quoteMatched = true;
            break;
          }
        }
      } else if (qWords.length >= 1) {
        quoteMatched = qWords.some(w => w.length >= 4 && contentN.includes(w));
      }
    }

    if (!quoteMatched) {
      errors.push(`quote_not_found:${cid}`);
      continue; // Skip invalid citation but DO NOT fail entire response if others are valid
    }

    validCitations.push({ chunk_id: cid, evidence_quote: quote });
  }
}

if (r) r.citations = validCitations;

// Grounding check across answer lines
if (modelAnswerable && validCitations.length > 0 && typeof r.answer === 'string') {
  const answerLines = r.answer
    .split(/\n+/)
    .map(stripAllowedPrefix)
    .map(s => s.trim())
    .filter(Boolean);

  const sourceTexts = validCitations
    .map(c => ctx.map?.[c.chunk_id]?.content)
    .filter(Boolean)
    .map(normalize);

  let groundedLines = 0;
  let factualLines = 0;

  for (let idx = 0; idx < answerLines.length; idx++) {
    const line = answerLines[idx];
    const nline = normalize(line);
    if (!nline || nline.length < 4) continue;

    if (/^(theo tai lieu|quy dinh|nguon|thong tin trong tai lieu|cu the|chi tiet|luu y|noi dung|tom tat|can cu|nhu sau)$/.test(nline)) continue;
    if (idx === 0 && /(nhu sau|bao gom|cac noi dung|quy dinh|chi tiet|sau day):?$/.test(nline)) continue;
    if (/(lien he|phong nhan su|thac mac|ho tro)/.test(nline)) continue;

    factualLines++;
    let directMatch = sourceTexts.some(src => src.includes(nline));
    if (!directMatch && nline.length >= 6) {
      const words = nline.split(/\s+/).filter(w => w.length >= 2);
      if (words.length >= 3) {
        for (let wi = 0; wi <= words.length - 3; wi++) {
          const sub = words.slice(wi, wi + 3).join(' ');
          if (sourceTexts.some(src => src.includes(sub))) {
            directMatch = true;
            break;
          }
        }
      } else if (words.length >= 1) {
        const sub = words.join(' ');
        if (sourceTexts.some(src => src.includes(sub))) {
          directMatch = true;
        }
      }
    }

    if (directMatch) {
      groundedLines++;
    }
  }

  const passRatio = factualLines <= 2 ? (groundedLines >= 1) : (groundedLines / factualLines >= 0.4);
  if (factualLines > 0 && !passRatio) {
    errors.push('answer_contains_unsupported_text');
  }
}

// Validator ONLY blocks if model claimed answerable but NO valid citation matched chunk content,
// OR if answer contains unsupported text. It does NOT block if 1 out of multiple citations had a typo.
const validatorBlocked = modelAnswerable && (
  validCitations.length === 0 ||
  errors.includes('answer_contains_unsupported_text')
);

if (!modelAnswerable) {
  r = {
    answerable: false,
    answer: NO,
    citations: [],
    missing_info: r?.missing_info || 'Tài liệu truy xuất được chưa đủ căn cứ để trả lời.'
  };
} else if (validatorBlocked) {
  r = {
    answerable: false,
    answer: NO,
    citations: [],
    missing_info: 'Câu trả lời không vượt qua kiểm tra căn cứ trích dẫn (grounding/citation).'
  };
} else {
  r.answerable = true;
  r.citations = validCitations;
  r.missing_info = '';
}

// Nhóm nguồn trích dẫn
const docGroups = new Map();
for (const c of (r.citations || [])) {
  const s = ctx.map?.[c.chunk_id];
  if (!s) continue;
  const docKey = s.doc_version_id || s.document_id || `${s.title}:::${s.doc_number || ''}`;
  if (!docGroups.has(docKey)) {
    docGroups.set(docKey, {
      title: s.title || 'Văn bản nội bộ',
      doc_number: s.doc_number || '',
      version: s.version || 1,
      effective_date: s.effective_date || '',
      status: s.status || 'active',
      sections: []
    });
  }
  const group = docGroups.get(docKey);
  const path = String(s.section_path || '').trim();
  if (path && !group.sections.includes(path)) group.sections.push(path);
}

const sources = Array.from(docGroups.values()).map(g => {
  const parts = [];
  if (g.doc_number && g.doc_number !== 's/n') parts.push(g.doc_number);
  parts.push(`v${g.version}`);
  if (g.effective_date) parts.push(`hiệu lực từ ${g.effective_date}`);
  if (g.status === 'testing') parts.push('bản kiểm thử/dự thảo');
  const meta = parts.length ? ` (${parts.join(', ')})` : '';
  const secStr = g.sections.length ? ` – Căn cứ: ${g.sections.join('; ')}` : '';
  return `• **${g.title}**${meta}${secStr}`;
});

let formattedReply = r.answer;
if (r.answerable && sources.length > 0) {
  formattedReply += '\n\n**Nguồn:**\n' + sources.join('\n');
}

const flatSources = (r.citations || []).map(c => {
  const chunk = ctx.map?.[c.chunk_id] || {};
  return {
    id: c.chunk_id,
    title: chunk.title || '',
    doc_number: chunk.doc_number || '',
    section_path: chunk.section_path || '',
    effective_date: chunk.effective_date || '',
    version: chunk.version || 1,
    status: chunk.status || 'active',
    doc_version_id: chunk.doc_version_id || null,
    evidence_quote: c.evidence_quote || '',
    content: chunk.content || ''
  };
});

const docVersionIds = [...new Set(flatSources.map(s => s.doc_version_id).filter(Boolean))];
const bestSim = $('RRF').first()?.json?.best_sim || 0;

return [{ json: {
  raw,
  reply: formattedReply,
  answerable: r.answerable,
  sources: flatSources,
  doc_versions: docVersionIds,
  best_sim: bestSim,
  errors,
  missing_info: r.missing_info || '',
  validator_blocked: validatorBlocked,
  debug: {
    rewritten: $('Prep').first()?.json?.rewritten || null,
    original_query: $('Prep').first()?.json?.message || '',
    keyword_text: $('Prep').first()?.json?.keyword_text || '',
    best_sim: bestSim,
    dense_count: $('RRF').first()?.json?.dense_count || 0,
    keyword_count: $('RRF').first()?.json?.keyword_count || 0,
    rrf_count: $('RRF').first()?.json?.rrf_count || 0,
    n_chunks: ctx.n || 0,
    validator_blocked: validatorBlocked,
    validation_errors: errors,
    valid_citations: validCitations,
    raw
  }
} }];

const HR_CONTACT = '028 1234 5678 hoặc hr@sotrans.vn';
const bestSim = $('RRF').first()?.json?.best_sim || 0;
return [{ json: {
  reply: `Hiện tại tài liệu nội bộ mình được cung cấp chưa có thông tin về nội dung bạn hỏi. Bạn vui lòng liên hệ trực tiếp phòng Nhân sự: ${HR_CONTACT}.`,
  answerable: false,
  best_sim: bestSim,
  sources: [],
  doc_versions: [],
  debug: { best_sim: bestSim }
} }];

